  val.innerHTML='';cells=[];
  for(var i=0;i<s.length;i++){
    if(s[i]===','||s[i]==='.'){var sp=document.createElement('span');sp.className='odo-hero-price-sep';sp.textContent=s[i];val.appendChild(sp);cells.push(null);continue;}
