      s.className = "t22-hero-ticker-num";
      s.textContent = String(d);
      reel.appendChild(s);
    }
    col.appendChild(reel);
    host.appendChild(col);
  }
}
function paint(host, str) {
  if (host.childElementCount !== str.length) build(host, str.length);
  for (var i = 0; i < str.length; i++) {
    var reel = host.children[i].firstChild;
    reel.style.transitionDelay = reduce ? "0ms" : ((str.length - 1 - i) * 55) + "ms";
    reel.style.transform = "translateY(-" + str.charAt(i) + "em)";
  }
}
function render() {
  var txt = price.toFixed(2);
  var parts = txt.split(".");
  paint(intEl, parts[0]);
  paint(decEl, parts[1]);
  var diff = price - 176.01;
  var pct = (diff / 176.01) * 100;
  var up = diff >= 0;
  chgEl.textContent = (up ? "▲ +" : "▼ −") + Math.abs(diff).toFixed(2) + " (" + (up ? "+" : "−") + Math.abs(pct).toFixed(2) + "%)";
