var dot = root.querySelector(".t22-spark-price-dot");
var valEl = root.querySelector(".t22-spark-price-val");
var chgEl = root.querySelector(".t22-spark-price-chg");
var W = 300, H = 52, PAD = 11, open = 424.76;
var pts = [], v = open;
for (var i = 0; i < 46; i++) { v += (Math.random() - 0.53) * 2.6; pts.push(v); }
pts[pts.length - 1] = 418.62;

function draw(animate) {
  var lo = Math.min.apply(null, pts), hi = Math.max.apply(null, pts);
  var span = (hi - lo) || 1, n = pts.length, d = "", ax = "", x, y;
  for (var i = 0; i < n; i++) {
    x = PAD + (i / (n - 1)) * (W - PAD * 2);
    y = H - 5 - ((pts[i] - lo) / span) * (H - 12);
