  }
  line.setAttribute("d", d);
  area.setAttribute("d", d + "L" + (W - PAD) + " " + H + "L" + PAD + " " + H + "Z");
  var last = pts[n - 1];
  dot.style.left = (((W - PAD) / W) * 100) + "%";
  dot.style.top = (((H - 5 - ((last - lo) / span) * (H - 12)) / H) * 100) + "%";
  var up = last >= open;
  root.classList.toggle("t22-spark-price--up", up);
